head.script:
gridView.setColumnIoFormat({
             colIndex : 0,
             //colIndex : "col1",
             ioFormat : "yyyyMMdd",
             calendarDisplayFormat : "yyyy-MM-dd" // 동작안됨
             //dateMask : "yyyy-MM-dd" // 동작안됨
});


	scwin.Dbclick = function(id) {
		var el = WebSquare.wUnit.getDomById(id);
		scwin.fireDbClick(el);
	}
	scwin.fireDbClick = function(node) {
		if (document.createEventObject) {
			node.fireEvent('ondbclick');
		} else if (document.createEvent) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('dblclick', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.ondbclick == 'function') {
			node.ondbclick();
		}
	}	
	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('G_gridView__col1_calendar_currentDate').innerText == '2016-12-30';
	}
	function unitTest(){
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView_cell_0_0')");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_gridView__col1_img').click()");
		WebSquare.wUnit.addCommand("pause", "400");			
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	unitTest();
